     1→/**
     2→ * Path utilities for Viben configuration files
     3→ */
     4→import { homedir } from "node:os";
     5→import { join } from "node:path";
     6→
     7→/**
     8→ * Get the Viben state directory path
     9→ * Default: ~/.viben
    10→ * Can be overridden with VIBEN_STATE_DIR environment variable
    11→ */
    12→export function getStateDir(): string {
    13→  return process.env.VIBEN_STATE_DIR || join(homedir(), ".viben");
    14→}
    15→
    16→/**
    17→ * Get the path to the global config file
    18→ */
    19→export function getConfigPath(): string {
    20→  return join(getStateDir(), "config.yaml");
    21→}
    22→
    23→/**
    24→ * Get the path to the providers config file
    25→ */
    26→export function getProvidersPath(): string {
    27→  return join(getStateDir(), "providers.yaml");
    28→}
    29→
    30→/**
    31→ * Get the path to the models config file
    32→ */
    33→export function getModelsPath(): string {
    34→  return join(getStateDir(), "models.yaml");
    35→}
    36→
    37→/**
    38→ * Get the agents directory path
    39→ */
    40→export function getAgentsDir(): string {
    41→  return join(getStateDir(), "agents");
    42→}
    43→
    44→/**
    45→ * Get the path to a specific agent's directory
    46→ */
    47→export function getAgentDir(agentId: string): string {
    48→  return join(getAgentsDir(), agentId);
    49→}
    50→
    51→/**
    52→ * Get the path to an agent's config file (AGENTS.md)
    53→ */
    54→export function getAgentConfigPath(agentId: string): string {
    55→  return join(getAgentDir(agentId), "AGENTS.md");
    56→}
    57→
    58→/**
    59→ * Get the path to an agent's MCP servers config
    60→ */
    61→export function getAgentMcpServersPath(agentId: string): string {
    62→  return join(getAgentDir(agentId), "mcp_servers.json");
    63→}
    64→
    65→/**
    66→ * Get the path to an agent's skills directory
    67→ */
    68→export function getAgentSkillsDir(agentId: string): string {
    69→  return join(getAgentDir(agentId), "skills");
    70→}
    71→
    72→/**
    73→ * Get the path to an agent's memory directory
    74→ */
    75→export function getAgentMemoryDir(agentId: string): string {
    76→  return join(getAgentDir(agentId), "memory");
    77→}
    78→
    79→/**
    80→ * Get the path to an agent's sessions directory
    81→ */
    82→export function getAgentSessionsDir(agentId: string): string {
    83→  return join(getAgentDir(agentId), ".agent_sessions");
    84→}
