     1→/**
     2→ * Idea Store
     3→ *
     4→ * Storage utilities for managing idea sessions and idea files.
     5→ *
     6→ * Directory Structure:
     7→ * .viben/
     8→ * └── ideas/
     9→ *     └── <date>-<slug>/           # Session directory
    10→ *         ├── idea.json            # Session metadata
    11→ *         ├── idea_<type>_<name1>.md
    12→ *         └── idea_<type>_<name2>.md
    13→ *
    14→ * docs/
    15→ * └── idea-types/                  # Idea type prompts (builtin + custom)
    16→ *     └── <type>.md                # Copied from templates via `viben init`
    17→ */
    18→import {
    19→  existsSync,
    20→  mkdirSync,
    21→  readdirSync,
    22→  readFileSync,
    23→  writeFileSync,
    24→  unlinkSync,
    25→  rmSync,
    26→} from "node:fs";
    27→import { join, resolve } from "node:path";
    28→import matter from "gray-matter";
    29→import { getTemplatesDir } from "../../utils/templates";
    30→
    31→import {
    32→  CUSTOM_IDEA_TYPES_DIR,
    33→  IDEAS_DIR,
    34→  IDEA_JSON_FILE,
    35→  IDEA_FILE_PREFIX,
    36→  DEFAULT_MAX_IDEAS,
    37→  BUILTIN_IDEA_TYPES,
    38→  type IdeaType,
    39→  type IdeaTypeSource,
    40→  type IdeaStatus,
    41→  type Idea,
    42→  type IdeaSession,
    43→  type IdeaListOptions,
    44→  type RawIdeaSession,
    45→  isValidEffortLevel,
    46→  isValidIdeaStatus,
    47→  getIdeaIdPrefix,
    48→  parseRawSession,
    49→  generateShortUuid,
    50→} from "./types";
    51→
    52→// =============================================================================
    53→// Constants
    54→// =============================================================================
    55→
    56→/** .viben directory name */
    57→const DIR_VIBEN = ".viben";
    58→
    59→/**
    60→ * Built-in type descriptions (fallback when prompt file doesn't exist)
    61→ */
    62→const BUILTIN_TYPE_DESCRIPTIONS: Record<string, string> = {
    63→  code_improvements: "代码改进 - 基于现有模式的改进机会",
    64→  code_quality: "代码质量 - 代码质量改进和重构模式",
    65→  documentation_gaps: "文档缺失 - 缺失或不足的文档",
    66→  performance_optimizations: "性能优化 - 性能瓶颈和优化技术",
    67→  security_hardening: "安全加固 - 安全漏洞和加固措施",
    68→  ui_ux_improvements: "UI/UX 改进 - 视觉和交互增强",
    69→};
    70→
    71→// =============================================================================
    72→// Path Utilities
    73→// =============================================================================
    74→
    75→/**
    76→ * Get date prefix in MM-DD format
    77→ * @internal - Not exported to avoid conflicts with viben-workspace.ts
    78→ */
    79→function getDatePrefix(): string {
    80→  const now = new Date();
    81→  const month = String(now.getMonth() + 1).padStart(2, "0");
    82→  const day = String(now.getDate()).padStart(2, "0");
    83→  return `${month}-${day}`;
    84→}
    85→
    86→/**
    87→ * Get the ideas directory path
    88→ *
    89→ * @param repoRoot - Repository root path
    90→ * @param customOutput - Optional custom output directory
    91→ * @returns Absolute path to ideas directory
    92→ */
    93→export function getIdeasDir(repoRoot: string, customOutput?: string): string {
    94→  if (customOutput) {
    95→    return resolve(repoRoot, customOutput);
    96→  }
    97→  return join(repoRoot, DIR_VIBEN, IDEAS_DIR);
    98→}
    99→
   100→/**
   101→ * Get the idea types directory path
   102→ *
   103→ * All idea types (builtin + custom) are stored in docs/idea-types/.
   104→ * Builtin types are copied there by `viben init`.
   105→ *
   106→ * @param repoRoot - Repository root path
   107→ * @returns Absolute path to idea types directory
   108→ */
   109→export function getIdeaTypesDir(repoRoot: string): string {
   110→  return join(repoRoot, CUSTOM_IDEA_TYPES_DIR);
   111→}
   112→
   113→/**
   114→ * Get a specific idea session directory path
   115→ *
   116→ * @param repoRoot - Repository root path
   117→ * @param sessionId - Session ID (e.g., "03-11-api-improvement")
   118→ * @returns Absolute path to session directory
   119→ */
   120→export function getIdeaSessionDir(repoRoot: string, sessionId: string): string {
   121→  return join(getIdeasDir(repoRoot), sessionId);
   122→}
   123→
   124→/**
   125→ * Get the idea.json file path within a session directory
   126→ *
   127→ * @param sessionDir - Session directory path
   128→ * @returns Path to idea.json file
