   132→}
   133→
   134→/**
   135→ * Get the idea markdown file path for a specific type
   136→ *
   137→ * @param sessionDir - Session directory path
   138→ * @param type - Idea type name (e.g., "code_improvements")
   139→ * @returns Path to idea_<type>.md file
   140→ */
   141→export function getIdeaMarkdownPath(sessionDir: string, type: string): string {
   142→  return join(sessionDir, `${IDEA_FILE_PREFIX}${type}.md`);
   143→}
   144→
   145→/**
   146→ * Get the prompt file path for a specific idea type
