   519→/**
   520→ * Delete a custom idea type
   521→ *
   522→ * Removes the markdown file from docs/idea-types/.
   523→ *
   524→ * @param repoRoot - Repository root path
   525→ * @param typeName - Name of the type to delete
   526→ */
   527→export function deleteIdeaType(repoRoot: string, typeName: string): void {
   528→  const promptPath = getIdeaTypePromptPath(repoRoot, typeName);
   529→
   530→  if (!existsSync(promptPath)) {
   531→    throw new Error(`Idea type file not found: ${promptPath}`);
   532→  }
   533→
   534→  unlinkSync(promptPath);
   535→}
