   541→/**
   542→ * Generate a session ID
   543→ *
   544→ * Format: MM-DD-<slug>
   545→ *
   546→ * @param types - Array of types being generated
   547→ * @returns Session ID string
   548→ */
   549→export function generateSessionId(types: string[]): string {
   550→  const datePrefix = getDatePrefix();
   551→
   552→  // Generate slug from types
   553→  let slug: string;
   554→  if (types.length === 1) {
   555→    // Single type: use type name
   556→    slug = types[0].replace(/_/g, "-");
   557→  } else if (types.length <= 3) {
   558→    // Few types: abbreviate each
   559→    slug = types.map((t) => getIdeaIdPrefix(t)).join("-");
   560→  } else {
   561→    // Many types: use "mixed"
   562→    slug = "mixed";
   563→  }
   564→
   565→  return `${datePrefix}-${slug}`;
   566→}
