   626→/**
   627→ * List all sessions
   628→ *
   629→ * @param repoRoot - Repository root path
   630→ * @param customOutput - Optional custom output directory
   631→ * @returns Array of session directories (sorted by date, newest first)
   632→ */
   633→export function listSessions(
   634→  repoRoot: string,
   635→  customOutput?: string
   636→): string[] {
   637→  const ideasDir = getIdeasDir(repoRoot, customOutput);
   638→  if (!existsSync(ideasDir)) {
   639→    return [];
   640→  }
   641→
   642→  try {
   643→    const dirs = readdirSync(ideasDir, { withFileTypes: true });
   644→    return dirs
   645→      .filter((d) => d.isDirectory())
   646→      .filter((d) => existsSync(join(ideasDir, d.name, IDEA_JSON_FILE)))
   647→      .map((d) => join(ideasDir, d.name))
   648→      .sort((a, b) => {
   649→        // Sort by directory name (which includes date prefix)
   650→        const aName = a.split("/").pop() || "";
   651→        const bName = b.split("/").pop() || "";
   652→        return bName.localeCompare(aName);
   653→      });
   654→  } catch {
   655→    return [];
   656→  }
   657→}
