   662→ * @param repoRoot - Repository root path
   663→ * @param customOutput - Optional custom output directory
   664→ * @returns Session directory path or null
   665→ */
   666→export function getLatestSession(
   667→  repoRoot: string,
   668→  customOutput?: string
   669→): string | null {
   670→  const sessions = listSessions(repoRoot, customOutput);
   671→  return sessions.length > 0 ? sessions[0] : null;
   672→}
