   820→/**
   821→ * Write a single idea to its own file
   822→ *
   823→ * @param sessionDir - Session directory path
   824→ * @param idea - Idea to write
   825→ * @returns The filename that was written
   826→ */
   827→export function writeSingleIdeaToFile(sessionDir: string, idea: Idea): string {
   828→  // Use name if available, fallback to id
   829→  const ideaName = idea.name || idea.id;
   830→  const filePath = getSingleIdeaFilePath(sessionDir, idea.type, ideaName);
   831→  const fileName = getSingleIdeaFileName(idea.type, ideaName);
   832→
   833→  const frontmatter: string[] = [
   834→    "---",
   835→    `id: ${idea.id}`,
   836→    `type: ${idea.type}`,
   837→    `name: ${ideaName}`,
   838→    `title: ${idea.title}`,
   839→    `description: ${idea.description}`,
   840→    `rationale: ${idea.rationale}`,
   841→    `estimated_effort: ${idea.estimatedEffort}`,
   842→    `status: ${idea.status}`,
   843→    `promoted_to: ${idea.promotedTo || "null"}`,
   844→    `created_at: ${idea.created_at}`,
   845→  ];
   846→
   847→  // Add affected files to frontmatter as YAML array
   848→  if (idea.affectedFiles && idea.affectedFiles.length > 0) {
   849→    frontmatter.push("affected_files:");
   850→    for (const file of idea.affectedFiles) {
   851→      frontmatter.push(`  - ${file}`);
   852→    }
   853→  }
   854→
   855→  // Add existing patterns to frontmatter as YAML array
   856→  if (idea.existingPatterns && idea.existingPatterns.length > 0) {
   857→    frontmatter.push("existing_patterns:");
   858→    for (const pattern of idea.existingPatterns) {
   859→      frontmatter.push(`  - ${pattern}`);
   860→    }
   861→  }
   862→
   863→  frontmatter.push("---");
   864→
   865→  // Body contains implementation approach directly (no header needed)
   866→  const body = idea.implementationApproach || "";
   867→
   868→  const content = frontmatter.join("\n") + "\n\n" + body + "\n";
   869→  writeFileSync(filePath, content, "utf-8");
   870→
   871→  return fileName;
   872→}
   873→
   874→/**
   875→ * Write ideas - each idea to its own file
   876→ *
   877→ * @param sessionDir - Session directory path
   878→ * @param ideas - Array of ideas to write
   879→ * @returns Array of filenames that were written
   880→ */
   881→export function writeIdeasToSeparateFiles(
   882→  sessionDir: string,
   883→  ideas: Idea[]
   884→): string[] {
   885→  const files: string[] = [];
   886→  for (const idea of ideas) {
   887→    const fileName = writeSingleIdeaToFile(sessionDir, idea);
   888→    files.push(fileName);
   889→  }
   890→  return files;
   891→}
