  1024→export function updateIdea(
  1025→  filePath: string,
  1026→  ideaId: string,
  1027→  updates: Partial<Idea>
  1028→): boolean {
  1029→  const ideas = readIdeasFromFile(filePath);
  1030→  const index = ideas.findIndex((i) => i.id === ideaId);
  1031→
  1032→  if (index === -1) {
  1033→    return false;
  1034→  }
  1035→
  1036→  ideas[index] = { ...ideas[index], ...updates };
  1037→  writeIdeasToFile(filePath, ideas);
  1038→  return true;
  1039→}
