  1045→/**
  1046→ * Get all ideas from all sessions with optional filtering
  1047→ *
  1048→ * @param repoRoot - Repository root path
  1049→ * @param options - Optional filter options
  1050→ * @returns Array of Ideas
  1051→ */
  1052→export function getAllIdeas(
  1053→  repoRoot: string,
  1054→  options?: IdeaListOptions
  1055→): Idea[] {
  1056→  const sessionDirs = listSessions(repoRoot);
  1057→  const allIdeas: Idea[] = [];
  1058→
  1059→  for (const sessionDir of sessionDirs) {
  1060→    const sessionIdeas = getAllIdeasFromSession(sessionDir);
  1061→    allIdeas.push(...sessionIdeas);
  1062→  }
  1063→
  1064→  // Apply filters
  1065→  let filtered = allIdeas;
  1066→
  1067→  if (options?.type) {
  1068→    filtered = filtered.filter((idea) => idea.type === options.type);
  1069→  }
  1070→
  1071→  if (options?.effort) {
  1072→    filtered = filtered.filter(
  1073→      (idea) => idea.estimatedEffort === options.effort
  1074→    );
  1075→  }
  1076→
  1077→  if (options?.status) {
  1078→    filtered = filtered.filter((idea) => idea.status === options.status);
  1079→  }
  1080→
  1081→  return filtered;
  1082→}
