  1096→/**
  1097→ * Update an idea's status
  1098→ *
  1099→ * @param repoRoot - Repository root path
  1100→ * @param ideaId - Idea ID
  1101→ * @param status - New status
  1102→ * @param promotedTo - Optional task ID if promoting
  1103→ */
  1104→export function updateIdeaStatus(
  1105→  repoRoot: string,
  1106→  ideaId: string,
  1107→  status: string,
  1108→  promotedTo?: string
  1109→): void {
  1110→  const location = findIdeaById(repoRoot, ideaId);
  1111→  if (!location) {
  1112→    return;
  1113→  }
  1114→
  1115→  const updates: Partial<Idea> = {};
  1116→  if (isValidIdeaStatus(status)) {
  1117→    updates.status = status;
  1118→  }
  1119→  if (promotedTo !== undefined) {
  1120→    updates.promotedTo = promotedTo;
  1121→  }
  1122→
  1123→  updateIdea(location.filePath, ideaId, updates);
  1124→
  1125→  // Update session summary
  1126→  updateSessionSummary(location.sessionDir);
  1127→}
  1128→
  1129→/**
  1130→ * Remove an idea by ID
  1131→ *
  1132→ * @param repoRoot - Repository root path
  1133→ * @param ideaId - Idea ID
  1134→ * @returns True if removed, false if not found
  1135→ */
  1136→export function removeIdea(repoRoot: string, ideaId: string): boolean {
  1137→  const location = findIdeaById(repoRoot, ideaId);
  1138→  if (!location) {
  1139→    return false;
  1140→  }
  1141→
  1142→  const ideas = readIdeasFromFile(location.filePath);
  1143→  const filteredIdeas = ideas.filter((idea) => idea.id !== ideaId);
  1144→
  1145→  if (filteredIdeas.length === ideas.length) {
  1146→    return false; // Not found
  1147→  }
  1148→
  1149→  writeIdeasToFile(location.filePath, filteredIdeas);
  1150→
  1151→  // Update session summary
  1152→  updateSessionSummary(location.sessionDir);
  1153→
  1154→  return true;
  1155→}
  1156→
  1157→/**
  1158→ * Remove all ideas of a specific type
  1159→ *
  1160→ * @param repoRoot - Repository root path
  1161→ * @param type - Idea type to remove
  1162→ * @returns Number of ideas removed
  1163→ */
  1164→export function removeIdeasByType(repoRoot: string, type: string): number {
  1165→  const sessionDirs = listSessions(repoRoot);
  1166→  let removedCount = 0;
  1167→
  1168→  for (const sessionDir of sessionDirs) {
  1169→    const mdPath = getIdeaMarkdownPath(sessionDir, type);
  1170→
  1171→    if (existsSync(mdPath)) {
  1172→      const ideas = readIdeasFromFile(mdPath);
  1173→      removedCount += ideas.length;
  1174→
  1175→      // Remove the file
  1176→      unlinkSync(mdPath);
  1177→
  1178→      // Update session summary
  1179→      updateSessionSummary(sessionDir);
  1180→    }
  1181→  }
  1182→
  1183→  return removedCount;
  1184→}
  1185→
  1186→/**
  1187→ * Remove all ideas
  1188→ *
  1189→ * @param repoRoot - Repository root path
  1190→ * @returns Number of ideas removed
  1191→ */
  1192→export function removeAllIdeas(repoRoot: string): number {
  1193→  const sessions = listIdeaSessions(repoRoot);
  1194→  let removedCount = 0;
  1195→
  1196→  for (const session of sessions) {
  1197→    removedCount += session.summary.total_ideas;
  1198→    const sessionDir = getIdeaSessionDir(repoRoot, session.id);
  1199→
  1200→    // Remove entire session directory
  1201→    if (existsSync(sessionDir)) {
  1202→      rmSync(sessionDir, { recursive: true, force: true });
  1203→    }
  1204→  }
  1205→
  1206→  return removedCount;
  1207→}
  1208→
  1209→/**
  1210→ * Update session summary after modifying ideas
  1211→ *
  1212→ * @param sessionDir - Session directory path
  1213→ */
  1214→function updateSessionSummary(sessionDir: string): void {
  1215→  const session = readSessionMetadata(sessionDir);
  1216→  if (!session) {
  1217→    return;
  1218→  }
  1219→
  1220→  // Recalculate summary
  1221→  session.summary.total_ideas = 0;
  1222→  session.summary.by_type = {};
  1223→  session.summary.by_status = { draft: 0, promoted: 0, dismissed: 0 };
  1224→
  1225→  // Check which types still have files
  1226→  const remainingTypes: string[] = [];
  1227→
  1228→  for (const type of session.types) {
  1229→    const mdPath = getIdeaMarkdownPath(sessionDir, type);
  1230→    if (existsSync(mdPath)) {
  1231→      const ideas = readIdeasFromFile(mdPath);
  1232→
  1233→      if (ideas.length > 0) {
  1234→        remainingTypes.push(type);
  1235→        session.summary.by_type[type] = ideas.length;
  1236→        session.summary.total_ideas += ideas.length;
  1237→
  1238→        for (const idea of ideas) {
  1239→          if (idea.status in session.summary.by_status) {
  1240→            session.summary.by_status[idea.status as IdeaStatus]++;
  1241→          }
  1242→        }
  1243→      }
  1244→    }
  1245→  }
  1246→
  1247→  session.types = remainingTypes;
  1248→  session.updated_at = new Date().toISOString();
  1249→  writeIdeaSession(sessionDir, session);
  1250→}
