   168→export function registerProviderRoutes(fastify: FastifyInstance): void {
   169→  // ========================================================================
   170→  // Default Provider Management (MUST be registered before :id routes)
   171→  // ========================================================================
   172→
   173→  /**
   174→   * Get the default provider
   175→   * GET /api/providers/default
   176→   */
   177→  fastify.get("/api/providers/default", async () => {
   178→    const defaultProviderId = await providerManager.getDefault();
   179→    if (!defaultProviderId) {
   180→      return { default_provider_id: null };
   181→    }
   182→
   183→    const provider = await providerManager.getProvider(defaultProviderId);
   184→    return {
   185→      default_provider_id: defaultProviderId,
   186→      provider: provider ? toSnakeCaseProvider(provider) : null,
   187→    };
   188→  });
   189→
   190→  /**
   191→   * Set the default provider
   192→   * PUT /api/providers/default
   193→   */
   194→  fastify.put(
   195→    "/api/providers/default",
   196→    async (
   197→      request: FastifyRequest<{ Body: SetDefaultProviderBody }>,
   198→      reply: FastifyReply
   199→    ) => {
   200→      const { provider_id } = request.body;
   201→
   202→      if (!provider_id) {
   203→        reply.code(400);
   204→        return { error: "Provider ID is required" };
   205→      }
   206→
   207→      try {
   208→        await providerManager.setDefault(provider_id);
   209→        return {
   210→          success: true,
   211→          default_provider_id: provider_id,
   212→        };
   213→      } catch (e) {
   214→        reply.code(400);
   215→        return { error: e instanceof Error ? e.message : "Failed to set default provider" };
   216→      }
   217→    }
   218→  );
   219→
   220→  /**
   221→   * Reload providers configuration from disk
   222→   * POST /api/providers/reload
   223→   */
   224→  fastify.post("/api/providers/reload", async (_request: FastifyRequest, reply: FastifyReply) => {
   225→    try {
   226→      await providerManager.reload();
   227→      return {
   228→        success: true,
   229→        message: "Providers configuration reloaded",
   230→      };
   231→    } catch (e) {
   232→      reply.code(500);
   233→      return { error: e instanceof Error ? e.message : "Failed to reload configuration" };
   234→    }
   235→  });
