   237→  // ========================================================================
   238→  // Provider CRUD (with :id param - registered AFTER specific routes)
   239→  // ========================================================================
   240→
   241→  /**
   242→   * List all providers
   243→   * GET /api/providers
   244→   */
   245→  fastify.get("/api/providers", {
   246→    schema: {
   247→      description: "List all providers",
   248→      tags: ["providers"],
