## 1. `packages/core/src/config/paths.ts` — Path utilities

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/config/paths.ts`

The pattern is straightforward exported functions, no classes:

```ts
import { homedir } from "node:os";
import { join } from "node:path";

export function getStateDir(): string {
  return process.env.VIBEN_STATE_DIR || join(homedir(), ".viben");
}

export function getProvidersPath(): string {
  return join(getStateDir(), "providers.yaml");
}

// Every new subsystem gets its own path function:
export function getFooDir(): string {
  return join(getStateDir(), "foo");
}
export function getFooFilePath(id: string): string {
  return join(getFooDir(), `${id}.yaml`);
}
```

No class, no singleton. Each function calls `getStateDir()` freshly (respects `VIBEN_STATE_DIR` env override at call time).

