## 5. Gateway route file pattern — `providers.ts` and `models.ts`

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/providers.ts`
`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/models.ts`

The canonical pattern for a CRUD route file:

```ts
import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import { someSingleton } from "../../some-module";
import type { SomeType } from "../../types";

// ── Local request/response interfaces (snake_case) ────────────────────────
interface CreateFooBody { name: string; some_field?: string; }
interface UpdateFooBody { name?: string; some_field?: string; }

// ── Transform helper (camelCase internal → snake_case API) ─────────────────
function toApiShape(foo: InternalFoo): FooResponse { ... }

// ── Route registration ─────────────────────────────────────────────────────
export function registerFooRoutes(fastify: FastifyInstance): void {

  // Static/named routes BEFORE :id param routes (Fastify ordering matters)
  fastify.get("/api/foos/default", async () => { ... });
  fastify.put("/api/foos/default", async (req: FastifyRequest<{ Body: SetDefaultBody }>, reply) => { ... });

  // List
  fastify.get("/api/foos", {
    schema: { description: "...", tags: ["foos"], response: { 200: { ... } } }
  }, async (req: FastifyRequest<{ Querystring: FoosQuery }>) => {
    const items = await someSingleton.list();
    return { foos: items.map(toApiShape), total: items.length };
  });

  // Create  → 201
  fastify.post("/api/foos", async (req: FastifyRequest<{ Body: CreateFooBody }>, reply) => {
    if (!req.body.name) { reply.code(400); return { error: "name is required" }; }
    try {
      const item = await someSingleton.create(req.body);
      reply.code(201);
      return toApiShape(item);
    } catch (e) {
      reply.code(400);
      return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Get by ID
  fastify.get("/api/foos/:id", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    const item = await someSingleton.get(req.params.id);
    if (!item) { reply.code(404); return { error: `Not found: ${req.params.id}` }; }
    return toApiShape(item);
  });

  // Update  → PATCH
  fastify.patch("/api/foos/:id", async (
    req: FastifyRequest<{ Params: { id: string }; Body: UpdateFooBody }>,
    reply
  ) => {
    try {
      const updated = await someSingleton.update(req.params.id, req.body);
      return toApiShape(updated);
    } catch (e) {
      if (e instanceof Error && e.message.includes("not found")) {
        reply.code(404); return { error: `Not found: ${req.params.id}` };
      }
      reply.code(400); return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Delete
  fastify.delete("/api/foos/:id", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    try {
      await someSingleton.remove(req.params.id);
      return { success: true, deleted: req.params.id };
    } catch (e) {
      reply.code(e instanceof Error && e.message.includes("not found") ? 404 : 400);
      return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Action sub-routes (enable/disable/test)
  fastify.post("/api/foos/:id/enable", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    try {
      await someSingleton.setEnabled(req.params.id, true);
      return { success: true, id: req.params.id, enabled: true };
    } catch (e) { ... }
  });
}
```

**Key conventions to follow:**

- All request/response types defined locally at the top of the file as plain interfaces
- API response fields use `snake_case`; internal model fields may be `camelCase` — a `toApiShape()` transformer bridges them
- Named/static routes (`/default`, `/reload`, `/aliases`) registered BEFORE parameterized routes (`/:id`) to avoid Fastify treating "default" as an `:id` value
- Error handling: `reply.code(400/404/500)` then return `{ error: string }` — no thrown HTTP errors
- `schema:` object is optional but used on GET list endpoints for documentation
- Delete returns `{ success: true, deleted: id }`, not 204
- Singleton managers (like `providerManager`, `modelManager`) are imported from `../../providers` / `../../models` — no DI
